<?php require 'config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('/');$rid=(int)($_POST['rifa_id']??0);$s=$pdo->prepare("SELECT * FROM rifas WHERE id=? AND status='ativa'");$s->execute([$rid]);$r=$s->fetch();if(!$r)die('Rifa inválida');$nome=trim($_POST['nome']??'');if(!$nome)die('Informe seu nome.');try{$pdo->beginTransaction();$chosen=[];if($r['tipo']==='selecionavel'){$chosen=array_values(array_unique(array_map('intval',$_POST['numeros']??[])));if(!$chosen)throw new Exception('Escolha ao menos um número.');foreach($chosen as $n)if($n<0||$n>=$r['total_numeros'])throw new Exception('Número inválido.');}else{$q=max(1,min(100,(int)($_POST['quantidade']??1)));$st=$pdo->prepare("SELECT numero FROM bilhetes WHERE rifa_id=? AND status IN ('reservado','pago')");$st->execute([$rid]);$busy=array_flip(array_column($st->fetchAll(),'numero'));$avail=[];for($i=0;$i<$r['total_numeros'];$i++)if(!isset($busy[$i]))$avail[]=$i;if(count($avail)<$q)throw new Exception('Não há números suficientes.');shuffle($avail);$chosen=array_slice($avail,0,$q);}$codigo=strtoupper(bin2hex(random_bytes(5)));$total=count($chosen)*(float)$r['preco'];$p=$pdo->prepare('INSERT INTO pedidos(rifa_id,nome,telefone,email,quantidade,total,codigo) VALUES(?,?,?,?,?,?,?)');$p->execute([$rid,$nome,trim($_POST['telefone']??''),trim($_POST['email']??''),count($chosen),$total,$codigo]);$pid=$pdo->lastInsertId();$b=$pdo->prepare('INSERT INTO bilhetes(rifa_id,pedido_id,numero) VALUES(?,?,?)');foreach($chosen as $n)$b->execute([$rid,$pid,$n]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();die('Não foi possível reservar: '.e($e->getMessage()).' <a href="javascript:history.back()">Voltar</a>');}?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/style.css"><title>Pedido</title></head><body><main class="wrap"><div class="box"><h1>Reserva realizada 🎉</h1><p>Código: <b><?=e($codigo)?></b></p><p>Total: <b>R$ <?=number_format($total,2,',','.')?></b></p><p>Números: <b><?=e(implode(', ',array_map(fn($n)=>str_pad($n,strlen((string)($r['total_numeros']-1)),'0',STR_PAD_LEFT),$chosen)))?></b></p><p class="muted">Pagamento ainda não integrado. O administrador pode marcar o pedido como pago no painel.</p><a class="btn" href="index.php">Início</a></div></main></body></html>
